function refreshContext(scope){if(scope==='private')return;const p=state.projects.find(p=>p.id===scope);if(!p)return;let r=state.resources.find(r=>r.scope===scope&&r.kind==='context');if(!r){r={id:uid(),scope,owner:state.user,name:'PROJECT.md',kind:'context',folder:'root',history:[]};state.resources.push(r)}const rs=state.resources.filter(x=>x.scope===scope&&x.kind!=='context'),chs=state.channels.filter(c=>c.project===scope),messages=state.messages.filter(m=>chs.some(c=>c.id===m.channel));r.body=`# ${p.name}\n\n## Members\n${p.members.map(name).join(', ')}\n\n## Project agent\n${p.agent.name}: ${p.agent.retired?'retired':'assigned; execution not connected'}\n\n## Goals\n${(state.goals[scope]||[]).map(g=>`${g.done?'[x]':'[ ]'} ${g.name} — ${name(g.owner)}${g.agent?' + project agent':''}${g.due?' — '+g.due:''}`).join('\n')||'No goals yet.'}\n\n## Resources\n${rs.map(x=>`${x.name} (${x.id})`).join('\n')||'No resources yet.'}\n\n## Conversation sources\n${chs.map(c=>`#${c.name}: ${messages.filter(m=>m.channel===c.id).length} entries`).join('\n')}\n\n## Recent conversation\n${messages.slice(-6).map(m=>`${name(m.by)}: ${m.body}`).join('\n\n')||'No conversation yet.'}\n\n## Generation status\nThis orientation is maintained by local templates, not agent inference. Conversation entries remain source material; no decisions are inferred.\n`;revision(r,'Context template refreshed')}
