function chatMessage(m,inThread=false){const replies=state.messages.filter(x=>x.parent===m.id);return`<div class="chat-message"><span class="avatar">${initials(m.by)}</span><div class="message-main"><div class="message-author">${H(name(m.by))}<time>${new Date(m.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</time></div><div class="message-text">${H(m.body)}</div>${!inThread?`<button class="thread-link" data-thread="${m.id}">${replies.length?replies.length+' '+(replies.length===1?'reply':'replies'):'Reply in thread'}</button>`:''}</div></div>`}
