function agentBody(i){const p=currentProject();if(!p)return'<div class="agent-detail">Private agent execution is not connected.</div>';const mode=i.tab||'assignment';return tabs(mode,[['assignment','Assignment'],['context','Context'],['activity','Activity']],`data-agent-tab`)+(mode==='context'?`<pre class="context-markdown">${H(state.resources.find(r=>r.scope===p.id&&r.kind==='context')?.body||'')}</pre>`:mode==='activity'?`<div class="inline-status">No agent runtime is connected. These are local context events, not model executions.</div>${state.events.filter(e=>e.scope===p.id||state.resources.some(r=>r.id===e.resource&&r.scope===p.id)).slice(-10).reverse().map(e=>`<div class="history-entry">${H(e.action)}<small>${date(e.at)}</small></div>`).join('')}`:`<div class="agent-detail"><strong>${H(p.agent.name)}</strong><div class="state-line">${p.agent.retired?'Retired':'Assigned to this project'} · runtime not connected</div>This project has a persistent agent assignment. Conversations, goals, and resources form its starting context.<p>Context is currently maintained by local templates. Retrieval and autonomous model execution are not connected.</p><label class="inline-form">Assignment state<select id="agent-state"><option value="active" ${!p.agent.retired?'selected':''}>Assigned</option><option value="retired" ${p.agent.retired?'selected':''}>Retired</option></select></label></div>`)}
