function drawGraph(){graphNodes.forEach(n=>{const el=$(`[data-node="${n.id}"]`);if(el){el.style.left=n.x+'px';el.style.top=n.y+'px'}});graphLinks.forEach(([a,b],i)=>{const from=graphNodes.find(n=>n.id===a),to=graphNodes.find(n=>n.id===b),el=$(`[data-edge="${i}"]`);if(el){el.setAttribute('x1',from.x);el.setAttribute('y1',from.y);el.setAttribute('x2',to.x);el.setAttribute('y2',to.y)}})}
$$('[data-surface]').forEach(b=>b.onclick=()=>setSurface(b.dataset.surface));
$('#add').onclick=()=>{reveal=reveal?.type==='add'?null:{type:'add'};renderReveal()};$('#agent-target').onclick=()=>{addressed=!addressed;updateComposer();if(addressed)notice('Agent runtime is not connected. Messages can be retained as source context.')};
$('#zoom-out').onclick=()=>zoomTo(camera().z/1.25);$('#zoom-in').onclick=()=>zoomTo(camera().z*1.25);$('#zoom-level').onclick=()=>zoomTo(1);$('#fit').onclick=fitAll;
$('#identity').onclick=()=>{const candidates=people.map(p=>p.id),next=candidates[(candidates.indexOf(state.user)+1)%candidates.length];state.user=next;if(state.scope!=='private'&&!currentProject()?.members.includes(next))state.scope='private';state.channel=null;thread=null;graphSelected=null;render();notice('Local sample identity: '+name(next)+'. This is not authentication.')};
$('#composer').onsubmit=e=>{e.preventDefault();if(reveal?.type==='create')return;const input=$('#message'),body=input.value.trim();if(!body)return;if(!state.channel){if(state.scope==='private'){const c={id:uid(),owner:state.user,name:body.slice(0,32)};state.chats.push(c);state.channel=c.id}else state.channel=state.channels.find(c=>c.project===state.scope)?.id}if(!state.channel)return;state.messages.push({id:uid(),channel:state.channel,by:state.user,body:addressed?'@agent '+body:body,at:now(),parent:thread});input.value='';input.style.height='';refreshContext(state.scope);persist();updateComposer();if(state.surface==='canvas'){openModule('conversation');renderWorld()}else{inspectGraph('channel:'+state.channel)}renderRail()};
$('#message').oninput=e=>{e.target.style.height='auto';e.target.style.height=Math.min(120,e.target.scrollHeight)+'px'};$('#message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#composer').requestSubmit()}};
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='0'){e.preventDefault();fitAll()}else if(e.key==='-'||e.key==='_'){e.preventDefault();zoomTo(camera().z/1.25)}else if(e.key==='+'||e.key==='='){e.preventDefault();zoomTo(camera().z*1.25)}else if(e.key==='Escape'){reveal=null;renderReveal();if(graphSelected){graphSelected=null;renderWorld()}}});
window.addEventListener('resize',()=>applyCamera());
function graphMark(n){
 const r=state.resources.find(r=>r.id===n.resource);
 if(n.kind==='project')return '<span class="hub-mark"><i></i></span>';
 if(n.kind==='folder')return '<span class="branch-mark"><i></i><i></i><i></i></span>';
 if(r?.workbook){const sheet=r.workbook.sheets[0];return '<span class="cell-mark">'+Array.from({length:12},(_,n)=>'<i>'+H(String(ResourceViews.cellValue(sheet,ResourceViews.col(n%3)+(Math.floor(n/3)+1))).slice(0,7))+'</i>').join('')+'</span>'}
 if(r?.presentation)return '<span class="deck-mark"><b>'+H(r.presentation.slides[0]?.elements.find(e=>e.type==='text')?.text?.slice(0,16)||'')+'</b><i></i></span>';
 if(n.kind==='context')return '<span class="markdown-mark">md</span>';
 if(n.kind==='channel')return '<span class="thread-mark">'+icon('chat')+'</span>';
 const excerpt=r?.document?.blocks?.find(b=>b.text)?.text||r?.body||n.label;return '<span class="paper-mark"><b>'+H(excerpt.slice(0,28))+'</b><i></i><i></i><i></i></span>';
}
function markdownReading(text){return String(text||'').split(/\n\n+/).map(part=>part.startsWith('# ')?`<h2>${H(part.slice(2))}</h2>`:part.startsWith('## ')?`<h3>${H(part.slice(3))}</h3>`:`<p>${H(part).replace(/\n/g,'<br>')}</p>`).join('')}
function createResource(kind){const r={...ResourceViews.create(kind),id:uid(),scope:state.scope,owner:state.user,folder:'resources',history:[]};state.resources.push(r);revision(r,'Created');refreshContext(state.scope);renderRail();return r}
async function importResource(file,item){
 if(file.size>15*1024*1024){notice('Choose a file smaller than 15 MB.');return}
 try{let data;if(/\.(docx|xlsx|pptx)$/i.test(file.name)){const response=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name)},body:file});data=await response.json();if(!response.ok)throw Error(data.error||'Import failed.')}else if(/\.csv$/i.test(file.name)){const rows=parseCSV(await file.text()),cells={};rows.forEach((row,r)=>row.forEach((value,c)=>cells[ResourceViews.col(c)+(r+1)]={value:value!==''&&!isNaN(Number(value))?Number(value):value}));data={kind:'spreadsheet',body:'',workbook:{sheets:[{name:'Sheet 1',cells,columns:[]}]},source:{name:file.name,format:'CSV',mode:'preview'}}}else data={kind:'document',body:await file.text()};if(JSON.stringify(state).length+JSON.stringify(data).length*3>2000000)throw Error('This preview exceeds the browser storage budget. Try a smaller file.');const r={...data,id:uid(),name:file.name,scope:state.scope,owner:state.user,folder:'resources',history:[]};state.resources.push(r);revision(r,'Imported');refreshContext(state.scope);persist();renderRail();if(item){item.resource=r.id;item.tab='content';renderWorld()}else if(state.surface==='graph'){folderOpen.add('resources:'+state.scope);inspectGraph(r.id)}else openModule('document',r.id);notice('Imported '+file.name)}catch(e){notice(e.message.includes('JSON')?'Restart the preview with server.py to import Office files.':e.message)}
}
function parseCSV(text){const rows=[[]];let value='',quoted=false;for(let n=0;n<text.length;n++){const ch=text[n];if(ch==='"'){if(quoted&&text[n+1]==='"'){value+='"';n++}else quoted=!quoted}else if(ch===','&&!quoted){rows.at(-1).push(value);value=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[n+1]==='\n')n++;rows.at(-1).push(value);rows.push([]);value=''}else value+=ch}rows.at(-1).push(value);if(rows.at(-1).length===1&&rows.at(-1)[0]==='')rows.pop();return rows}
function directoryBody(i,type){const p=currentProject(),query=(i.directoryQuery||'').toLowerCase(),filter=i.directoryFilter||'all';const isPeople=type==='people';const all=isPeople?p.members.map(id=>({id,name:name(id),role:(state.directory||[]).find(x=>x.id===id)?.role||people.find(x=>x.id===id)?.role||'Member'})):(p.agents||[p.agent]).map((a,index)=>({...a,id:a.id||'agent-'+index,role:a.retired?'Retired':'Assigned'}));const matches=all.filter(x=>x.name.toLowerCase().includes(query)&&(filter==='all'||x.role.toLowerCase()===filter));const page=Math.min(i.directoryPage||0,Math.max(0,Math.ceil(matches.length/24)-1)),slice=matches.slice(page*24,(page+1)*24);return`<div class="directory-controls">${icon('search')}<input data-directory-query aria-label="Search ${type}" placeholder="Search ${type}…" value="${H(i.directoryQuery||'')}"><select data-directory-filter aria-label="Filter ${type}"><option value="all">All ${type}</option>${(isPeople?['Owner','Member','Guest']:['Assigned','Retired']).map(role=>`<option value="${role.toLowerCase()}" ${filter===role.toLowerCase()?'selected':''}>${role}</option>`).join('')}</select></div><div class="directory-list">${slice.map(x=>`<div class="directory-row">${isPeople?`<span class="avatar">${H(x.name.slice(0,1))}</span>`:icon('agent')}<span>${H(x.name)}${isPeople&&x.id===state.user?'<small>You</small>':''}</span>${isPeople?`<span class="directory-role">${H(x.role)}</span>`:`<select class="directory-state" data-assignment-state="${H(x.id)}" aria-label="${H(x.name)} assignment"><option value="assigned" ${x.retired?'':'selected'}>Assigned</option><option value="retired" ${x.retired?'selected':''}>Retired</option></select>`}</div>`).join('')||'<div class="directory-empty">No results</div>'}</div><div class="directory-footer"><span>${matches.length?`${page*24+1}–${Math.min(matches.length,(page+1)*24)}`:'0'} of ${matches.length}</span><span><button data-directory-page="${page-1}" aria-label="Previous results" ${page===0?'disabled':''}>${icon('back')}</button><button data-directory-page="${page+1}" aria-label="Next results" ${(page+1)*24>=matches.length?'disabled':''}>${icon('chevron')}</button></span></div>${!isPeople?'<p class="muted">Assignments are local. No agent runtime is connected.</p>':''}`}
function projectBody(i){const p=currentProject();if(!p)return'<p class="muted">Select a shared project.</p>';const tab=i.projectTab||'goals';const ctx=state.resources.find(r=>r.scope===state.scope&&r.kind==='context');return`<div class="project-tabs">${[['goals','Goals'],['knowledge','Knowledge'],['people','People'],['agents','Agents']].map(([id,label])=>`<button data-project-tab="${id}" class="${id===tab?'active':''}">${label}</button>`).join('')}</div><div class="project-content">${tab==='goals'?goalsBody():tab==='people'||tab==='agents'?directoryBody(i,tab):`<div class="knowledge-intro"><p>Project knowledge</p><span>Conversations, goals and references form the starting context for this project.</span></div>${ctx?`<button class="resource-list-row orientation-row" data-inline-resource="${ctx.id}">${icon('file')}<span>Project instructions<small>${H(ctx.name)}</small></span>${icon('chevron')}</button>`:''}<div class="knowledge-section-label">Files</div><div class="knowledge-resources">${scopeResources().filter(r=>r.kind!=='context').map(r=>`<button class="resource-list-row" data-inline-resource="${r.id}">${icon(r.workbook?'sheet':r.presentation?'slides':'file')}<span>${H(r.name)}</span><small>${H(name(r.owner))}</small></button>`).join('')||'<p class="muted">References you bring into the project appear here.</p>'}</div><div class="knowledge-section-label">Sources</div><div class="knowledge-source-list">${state.channels.filter(c=>c.project===state.scope).map(c=>`<div>${icon('hash')}<span>${H(c.name)}</span><small>${state.messages.filter(m=>m.channel===c.id).length} entries</small></div>`).join('')}</div>`}</div>`}
function bindProject(el,i){el.querySelectorAll('[data-assignment-state]').forEach(select=>select.onchange=()=>{const p=currentProject(),agent=(p.agents||[p.agent]).find((a,n)=>(a.id||'agent-'+n)===select.dataset.assignmentState);if(agent){agent.retired=select.value==='retired';refreshContext(state.scope);persist();renderWorld()}});el.querySelectorAll('[data-project-tab]').forEach(b=>b.onclick=()=>{i.projectTab=b.dataset.projectTab;i.directoryQuery='';i.directoryFilter='all';i.directoryPage=0;persist();renderWorld()});const input=el.querySelector('[data-directory-query]');if(input)input.oninput=()=>{const caret=input.selectionStart;i.directoryQuery=input.value;i.directoryPage=0;renderWorld();const field=document.querySelector(`[data-item="${i.id}"] [data-directory-query]`);field?.focus();field?.setSelectionRange(caret,caret)};el.querySelector('[data-directory-filter]')?.addEventListener('change',e=>{i.directoryFilter=e.target.value;i.directoryPage=0;renderWorld()});el.querySelectorAll('[data-directory-page]').forEach(b=>b.onclick=()=>{i.directoryPage=+b.dataset.directoryPage;renderWorld()})}
